use super::*;
use std::collections::BTreeMap;
struct F{values:BTreeMap<(u64,u8),u64>,used:Vec<(u64,u8)>}
impl Memory for F{fn read(&mut self,a:u64,w:u8)->Result<u64,&'static str>{let k=(a,w);let v=*self.values.get(&k).ok_or("MISSING_READ")?;if !self.used.contains(&k){if self.used.len()>=96{return Err("FIELD_BUDGET");}self.used.push(k);}Ok(v)}}
